/* =================================================
   HELPERS
================================================= */

function esc(value){
  return String(value ?? "")
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;")
    .replace(/'/g,"&#039;");
}

function normalize(value){
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g,"")
    .replace(/[^a-z0-9]/g,"");
}

/*
  Imagen de respaldo por producto/categoría.
  Primero se utiliza image_url de public.products si existe.
  Esto permite aprovechar las imágenes que ya estén asociadas
  a los 93 productos en Supabase.
*/
const imageLibrary = {
  papa:`data:image/jpeg;base64,`,
  tomate:`data:image/jpeg;base64,`,
  cebolla:`data:image/jpeg;base64,`,
  zanahoria:`data:image/jpeg;base64,`,
  limon:`data:image/jpeg;base64,`,
  lechuga:`data:image/jpeg;base64,`,
  brocoli:`data:image/jpeg;base64,`,
  coliflor:`data:image/jpeg;base64,`,
  repollo:`data:image/jpeg;base64,`,
  pepino:`data:image/jpeg;base64,`,
  palta:`data:image/jpeg;base64,`,
  aguacate:`data:image/jpeg;base64,`,
  platano:`data:image/jpeg;base64,`,
  manzana:`data:image/jpeg;base64,`,
  naranja:`data:image/jpeg;base64,`,
  mandarina:`data:image/jpeg;base64,`,
  fresa:`data:image/jpeg;base64,`,
  uva:`data:image/jpeg;base64,`,
  sandia:`data:image/jpeg;base64,`,
  melon:`data:image/jpeg;base64,`,
  mango:`data:image/jpeg;base64,`,
  pina:`data:image/jpeg;base64,`,
  ajo:`data:image/jpeg;base64,`,
  cebollachina:`data:image/jpeg;base64,`,
  aji:`data:image/jpeg;base64,`,
  pimiento:`data:image/jpeg;base64,`,
  espinaca:`data:image/jpeg;base64,`,
  apio:`data:image/jpeg;base64,`,
  beterraga:`data:image/jpeg;base64,`,
  camote:`data:image/jpeg;base64,`,
  yuca:`data:image/jpeg;base64,`,
  choclo:`data:image/jpeg;base64,`,
};

const fallbackByCategory = {
  verduras:`data:image/jpeg;base64,`,
  frutas:`data:image/jpeg;base64,`,
  tuberculos:`data:image/jpeg;base64,`,
  hierbas:`data:image/jpeg;base64,`,
  otros:`data:image/jpeg;base64,`
};

function fallbackImage(name,category){
  const n=normalize(name);
  for(const key of Object.keys(imageLibrary)){
    if(n.includes(normalize(key))) return imageLibrary[key];
  }
  const c=normalize(category);
  return fallbackByCategory[c] || fallbackByCategory.otros;
}

