function navigate(view){

  if(view==="home"){
    renderHome();
    return;
  }

  if(view==="categories"){
    currentCategory="Todos";
    renderHome();
    setTimeout(()=>{
      document.getElementById("categories")?.scrollIntoView({behavior:"smooth",block:"start"});
    },50);
    return;
  }

  if(view==="cart"){
    renderCart();
    return;
  }

  if(view==="orders"){
    renderOrders();
    return;
  }

  if(view==="account"){
    renderAccount();
    return;
  }
}

/* =================================================
   LOAD PRODUCTS
================================================= */

async function loadProducts(){
  // Una sola fuente de verdad: public.productos.
  // La versión anterior consultaba además public.products, lo que podía
  // provocar errores aunque la tabla productos estuviera correcta.
  try{
    const {data,error}=await client
      .from("productos")
      .select("*")
      .eq("activo",true)
      .order("id");

    if(error) throw error;

    products.length=0;

    (data || []).forEach(row=>{
      const rawCategory=String(row.categoria || "Verduras");
      const category = /tuberc/i.test(rawCategory) ? "Tubérculos"
        : /frut/i.test(rawCategory) ? "Frutas"
        : /hierb/i.test(rawCategory) ? "Hierbas"
        : "Verduras";
      const name=row.nombre || "Producto";

      products.push({
        id:row.id,
        name,
        category,
        unit:row.unidad || "kg",
        unitLabel:unitLabel(row.unidad),
        price:Number(row.precio)||0,
        image:row.imagen_url || fallbackImage(name,category)
      });
    });

    if(!products.length){
      loadDemoProducts();
    }else{
      renderHome();
    }
  }catch(error){
    console.error("Error cargando productos:",error);
    loadDemoProducts();
    renderHome();
  }
}

function loadDemoProducts(){
  products.length=0;
  demoProducts.forEach(p=>products.push({...p}));
}

